The evidence points to one root cause, with a clear propagation chain. Here is the write-up.

```json
{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_failed",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE span_name IN ('SELECT Order','OrderOtherRepository.findByAccountId') GROUP BY 1,2,3 ORDER BY n DESC",
          "claim": "Every SELECT Order database span in ts-order-other-service ends in Error after about 30 seconds, while normal traces show none."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, count(*) n FROM abnormal_logs WHERE service_name = 'ts-order-other-service' GROUP BY 1,2,3 ORDER BY n DESC",
          "claim": "ts-order-other-service logs HikariPool connection timeouts after 30000ms and MySQL communication link failures with SQLState 08S01."
        },
        {
          "kind": "trace",
          "sql": "WITH t0 AS (SELECT min(time) m FROM abnormal_traces) SELECT service_name, count(*) total, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(min(CASE WHEN attr_status_code='Error' THEN epoch(time - t0.m) END),1) first_err_s FROM abnormal_traces, t0 GROUP BY 1 ORDER BY first_err_s NULLS LAST",
          "claim": "ts-order-other-service is the first service to error, at about 0.2 s into the abnormal window, before any upstream caller."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-security-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, p.service_name AS caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name<>p.service_name GROUP BY 1,2 ORDER BY caller_err DESC, n DESC LIMIT 40",
          "claim": "ts-security-service calls to ts-order-other-service time out at about 30 s and its own requests return errors."
        }
      ]
    },
    {
      "from": "ts-security-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, p.service_name AS caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name<>p.service_name GROUP BY 1,2 ORDER BY caller_err DESC, n DESC LIMIT 40",
          "claim": "ts-preserve-service calls to ts-security-service fail or time out at about 60 s, with errors in the caller."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-seat-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, p.service_name AS caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name<>p.service_name GROUP BY 1,2 ORDER BY caller_err DESC, n DESC LIMIT 40",
          "claim": "ts-seat-service calls to ts-order-other-service return errors after about 30 s, and seat-service errors follow."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, p.service_name AS caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name<>p.service_name GROUP BY 1,2 ORDER BY caller_err DESC, n DESC LIMIT 40",
          "claim": "ts-travel2-service calls to ts-seat-service time out at about 60 s and return errors."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, p.service_name AS caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name<>p.service_name GROUP BY 1,2 ORDER BY caller_err DESC, n DESC LIMIT 40",
          "claim": "ts-route-plan-service calls to ts-travel2-service error out after tens of seconds."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS callee, p.service_name AS caller, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err, sum(CASE WHEN p.attr_status_code='Error' THEN 1 ELSE 0 END) caller_err, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.parent_span_id=p.span_id WHERE c.service_name<>p.service_name GROUP BY 1,2 ORDER BY caller_err DESC, n DESC LIMIT 40",
          "claim": "ts-travel-plan-service calls to ts-route-plan-service error out after tens of seconds."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) total, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name IN ('ts-ui-dashboard','ts-preserve-service') GROUP BY 1",
          "claim": "ts-preserve-service errors and roughly 60 s latencies surface in the user-facing ts-ui-dashboard requests."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, count(*) total, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(approx_quantile(duration,0.95)/1e6,1) p95ms FROM abnormal_traces WHERE service_name IN ('ts-ui-dashboard','ts-travel2-service') GROUP BY 1",
          "claim": "ts-travel2-service errors and timeouts surface in user-facing ts-ui-dashboard requests, whose p95 rises to about 20 s."
        }
      ]
    }
  ]
}
